    D2Lang::Unicode::UNISYS::STRING_ConvertCharToWchar(wszPrefixW, aHeaderBuffer, 0x154);
    D2Lang::Unicode::UNISYS::STRING_ConvertCharToWchar(wszMessageW, pszMessageText, 0x154);
    wszPrefixW[0x153] = L'\0';
    wszMessageW[0x153] = L'\0';
